package main

import (
	"strings"
	"testing"
)

func TestSpecReleasesGo_WritesBothReleasesAsVersions(t *testing.T) {
	got, err := specReleasesGo([]byte("# comment\nlakekeeper: v0.15.0\nlakekeeper-plus: v0.15.1\n"))
	if err != nil {
		t.Fatal(err)
	}
	src := string(got)
	for _, want := range []string{
		"// Code generated by prepare from api/openapi/spec-releases.yaml. DO NOT EDIT.",
		"package managementv1",
		`LakekeeperSpecRelease = "0.15.0"`,
		`LakekeeperPlusSpecRelease = "0.15.1"`,
	} {
		if !strings.Contains(src, want) {
			t.Errorf("generated source lacks %q:\n%s", want, src)
		}
	}
}

func TestSpecReleasesGo_RejectsAMissingOrMalformedRelease(t *testing.T) {
	for name, in := range map[string]string{
		"missing lakekeeper-plus": "lakekeeper: v0.15.0\n",
		"missing lakekeeper":      "lakekeeper-plus: v0.15.1\n",
		"not a release tag":       "lakekeeper: main\nlakekeeper-plus: v0.15.1\n",
		"no v prefix":             "lakekeeper: 0.15.0\nlakekeeper-plus: v0.15.1\n",
	} {
		t.Run(name, func(t *testing.T) {
			if _, err := specReleasesGo([]byte(in)); err == nil {
				t.Fatalf("no error for %q", in)
			}
		})
	}
}
